using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace ElswordPixel.Editor.Mine2CompatiblePublicLoaderControlledV21 {
 [InitializeOnLoad] public static class Worker {
  const string Active="Elsword.Mine2CompatiblePublicLoad.Active",Pending="Elsword.Mine2CompatiblePublicLoad.Pending",Output="Elsword.Mine2CompatiblePublicLoad.Output",Bundle="Elsword.Mine2CompatiblePublicLoad.Bundle",Started="Elsword.Mine2CompatiblePublicLoad.Started";static bool fault;static int phase,readyFrame;
  static Worker(){if(SessionState.GetBool(Active,false))Attach();}
  static void Attach(){EditorApplication.update-=Poll;EditorApplication.update+=Poll;Application.logMessageReceived-=Logged;Application.logMessageReceived+=Logged;}
  static void Logged(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)fault=true;}
  public static void Run(){if(!Application.isBatchMode||EditorApplication.isPlaying||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new InvalidOperationException("Idle batch Editor required");string output=Environment.GetEnvironmentVariable("EL_MINE2_COMPATIBLE_PUBLIC_LOAD_OUTPUT"),bundle=Environment.GetEnvironmentVariable("EL_MINE2_COMPATIBLE_BUNDLE");if(string.IsNullOrEmpty(output)||string.IsNullOrEmpty(bundle)||Directory.Exists(output))throw new InvalidOperationException("Fresh explicit compatible public-loader output required");DemoScene.ValidateMine2CompatibleEntryV21(bundle);Directory.CreateDirectory(output);SessionState.SetString(Output,output);SessionState.SetString(Bundle,bundle);SessionState.SetFloat(Started,(float)EditorApplication.timeSinceStartup);SessionState.SetBool(Active,true);SessionState.SetBool(Pending,true);fault=false;Attach();EditorSceneManager.OpenScene(DemoBuilder.ScenePath);EditorApplication.isPlaying=true;}
  static void Poll(){if(fault){Finish(2);return;}if(EditorApplication.timeSinceStartup-SessionState.GetFloat(Started,0)>180){Finish(3);return;}if(!EditorApplication.isPlaying||EditorApplication.isCompiling)return;var scene=UnityEngine.Object.FindFirstObjectByType<DemoScene>();if(!scene)return;try{string output=SessionState.GetString(Output,"");if(SessionState.GetBool(Pending,false)){SessionState.SetBool(Pending,false);scene.BeginMine2CompatiblePublicLoaderProbeV21(SessionState.GetString(Bundle,""),output);phase=0;return;}if(phase==0){if(!scene.Mine2PreviewActiveV21||!scene.ForestPreviewActive)return;phase=1;readyFrame=Time.frameCount+2;return;}if(Time.frameCount<readyFrame)return;if(phase==1){if(scene.Mine2CompatiblePublicProbeElapsedV21<2)return;scene.enabled=false;scene.ObserveAndExitMine2CompatiblePublicLoaderProbeV21();phase=2;readyFrame=Time.frameCount+2;return;}if(phase==2){var result=scene.FinishMine2CompatiblePublicLoaderProbeV21();File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(result,true));Finish(result.passed&&!fault?0:2);}}catch(Exception e){File.WriteAllText(Path.Combine(SessionState.GetString(Output,""),"failure.txt"),e.ToString());Debug.LogException(e);Finish(2);}}
  static void Finish(int code){SessionState.SetBool(Active,false);SessionState.SetBool(Pending,false);EditorApplication.update-=Poll;Application.logMessageReceived-=Logged;EditorApplication.Exit(code);}
 }
}
